<script lang="ts">
 import {page} from '$app/state';import {goto} from '$app/navigation';import {onDestroy,tick} from 'svelte';import Icon from './Icon.svelte';
 let {model,t,lang='de'}:{lang?:string;model:Record<string,any[]>;t:(key:string)=>string}=$props();let search=$state(''),status=$state('all'),scanning=$state(false),video=$state<HTMLVideoElement>(),stream:MediaStream|undefined,interval:ReturnType<typeof setInterval>|undefined,message=$state('');
 let visible=$derived(model.vessels.filter(v=>(v.name+' '+v.code).toLowerCase().includes(search.toLowerCase())).filter(v=>status==='all'||v.status===status).filter(v=>!page.url.searchParams.get('vessel')||v.id===page.url.searchParams.get('vessel')));
 const number=(v:any)=>new Intl.NumberFormat(lang,{maximumFractionDigits:2}).format(Number(v));
 function stop(){scanning=false;stream?.getTracks().forEach(track=>track.stop());if(interval)clearInterval(interval);}
 onDestroy(stop);
 async function scan(){const Detector=(window as any).BarcodeDetector;if(!Detector){message=t('manualSearch');return;}scanning=true;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});await tick();const camera=video;if(!camera){stop();return;}camera.srcObject=stream;await camera.play();const detector=new Detector({formats:['qr_code']});interval=setInterval(async()=>{try{const codes=await detector.detect(camera);if(codes[0]){const url=new URL(codes[0].rawValue);if(url.origin===location.origin&&url.pathname==='/app/cellar'){stop();await goto(url.pathname+url.search);}}}catch{message=t('manualSearch');}},600);}catch{message=t('manualSearch');stop();}}
</script>
<section class="card"><div class="tank-heading"><h2>{t('uxVessels')} <span class="pill">{visible.length}</span></h2><button class="secondary" onclick={()=>scanning?stop():scan()}>{scanning?t('done'):t('scanQr')}</button></div><div class="search"><label><span class="sr-only">{t('search')}</span><input type="search" bind:value={search} placeholder={t('search')+' · '+t('code')}/></label><label><span class="sr-only">{t('status')}</span><select bind:value={status}>{#each ['all','ready','cleaning','blocked'] as value}<option value={value}>{t(value)}</option>{/each}</select></label>{#if page.url.searchParams.has('vessel')}<a href="/app/cellar">{t('all')}</a>{/if}</div>{#if scanning}<video bind:this={video} autoplay muted playsinline><track kind="captions" /></video>{/if}{#if message}<p role="status" class="notice">{message}</p>{/if}<div class="tanks">{#each visible as vessel}{@const positions=model.positions.filter(p=>p.vessel_id===vessel.id&&Number(p.quantity_l)>0)}{@const volume=positions.reduce((sum,p)=>sum+Number(p.quantity_l),0)}{@const percent=Number(vessel.capacity_l)>0?Math.min(100,volume/Number(vessel.capacity_l)*100):0}<article class:blocked={vessel.status==='blocked'}><div class="vessel-top"><span class={'pill '+(vessel.status==='ready'?'good':vessel.status==='blocked'?'bad':'warning')}>{t(vessel.status)}</span><Icon name={vessel.kind==='barrel'?'bottling':'cellar'} size={19}/></div><a class="vessel-title" href={'/app/cellar?vessel='+vessel.id}><strong>{vessel.code}</strong><span>{vessel.name}</span></a><div class="volume"><strong>{number(volume)} <small>L</small></strong><span>{number(percent)}%</span></div><meter min="0" max={Number(vessel.capacity_l)} value={volume} aria-label={vessel.code+' · '+t('physical')}>{number(volume)} L</meter><p class="capacity">{t('capacity_l')}: {number(vessel.capacity_l)} L</p><div class="lots">{#each positions as position}<span><i></i>{position.lot_code} · {number(position.quantity_l)} L</span>{:else}<span>{t('empty')}</span>{/each}</div><details><summary>QR · {t('download')}</summary><a href={'/api/qr/'+vessel.id} download={'vinea-'+vessel.code+'.png'}><img src={'/api/qr/'+vessel.id} alt={'QR '+vessel.code} width="130" height="130" loading="lazy" /></a></details></article>{:else}<p class="empty-state">{t('uxNoResults')}</p>{/each}</div></section>
<style>.tank-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}.tank-heading h2{margin:0;display:flex;gap:9px;align-items:center}.tank-heading button{font-size:11px}.search{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.search input{width:280px;max-width:100%;font-size:12px}.search select{min-width:150px;font-size:12px}.tanks{display:grid;grid-template-columns:repeat(auto-fill,minmax(225px,1fr));gap:15px;margin-top:20px}.tanks article{background:#fff;padding:19px;border:1px solid #dce7df;border-radius:11px;min-width:0}.tanks article.blocked{background:#fffdfb;border-color:#ecdcd5}.vessel-top{display:flex;justify-content:space-between;align-items:center;color:var(--muted)}.vessel-title{display:grid;gap:5px;text-decoration:none;margin:18px 0}.vessel-title strong{font-size:15px;letter-spacing:-.2px}.vessel-title span{font-size:11px;color:var(--muted);min-height:34px}.volume{display:flex;justify-content:space-between;align-items:end;margin:15px 0 4px}.volume strong{font-size:24px;font-weight:650;letter-spacing:-.7px}.volume small{font-size:11px;color:var(--muted);font-weight:400}.volume>span{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}meter{width:100%;height:14px;appearance:none}meter::-webkit-meter-bar{background:#eaf0ec;border:0;border-radius:5px;height:8px}meter::-webkit-meter-optimum-value{background:#378c65;border-radius:5px}meter::-moz-meter-bar{background:#378c65;border-radius:5px}.capacity{color:var(--muted);font-size:10px;margin:6px 0 15px}.lots{border-top:1px solid var(--line);padding-top:12px}.lots span{display:flex;align-items:center;gap:6px;font-size:10px;color:#527263}.lots i{width:5px;height:5px;background:#4c8e6c;border-radius:50%}details{margin-top:9px}summary{font-size:10px;cursor:pointer;color:var(--muted);padding:4px 0;min-height:34px}video{max-width:350px;width:100%;margin-top:20px}@media(max-width:640px){.tanks{grid-template-columns:1fr 1fr;gap:10px}.tanks article{padding:14px}.vessel-title strong{font-size:12px}.volume strong{font-size:20px}.search label,.search input{width:100%}}@media(max-width:380px){.tanks{grid-template-columns:1fr}}
</style>
